let patternReferenceShell=null,patternReferenceMountSignal=null,patternReferenceViewers=[],patternReferenceCache=null,patternReferenceDialogDispose=null,patternReferenceSettingsDispose=null;
function attachedPatternReference(){return state.draft.patternReference?.record?state.draft.patternReference:null;}
function referenceGrid(){
 const ref=attachedPatternReference();if(!ref)return null;if(patternReferenceCache?.record===ref.record)return patternReferenceCache.grid;
 try{const grid=PatternEngine.recordGrid(ref.record);patternReferenceCache={record:ref.record,grid};return grid;}catch{return null;}
}
function getPatternBlueprint(){const ref=attachedPatternReference(),grid=referenceGrid();if(!ref||!grid)return null;const size=draftDimensions(),offsetX=Math.round(Number(ref.offsetX)||0),offsetY=Math.round(Number(ref.offsetY)||0),withinBoard=offsetX>=0&&offsetY>=0&&offsetX+ref.record.width<=size.cols&&offsetY+ref.record.height<=size.rows;return{grid,offsetX,offsetY,opacity:ref.opacity,showCodes:ref.showCodes,visible:ref.blueprint===true&&withinBoard};}
function patternReferenceSave(){saveSoon();if(boardViewport?.invalidateScene)boardViewport.invalidateScene();else drawBoard();}
function referenceCanFit(){const ref=attachedPatternReference(),size=draftDimensions();return Boolean(ref&&ref.record.width<=size.cols&&ref.record.height<=size.rows);}
function patternReferenceInline(){const page=document.querySelector('.fixed-editor');return innerWidth>760&&(page?.getBoundingClientRect().width||innerWidth)>=800;}
function patternReferenceMarkup(ref,phone=false){
 const record=ref.record,mode=['original','color','codes'].includes(ref.displayMode)?ref.displayMode:'color',hasOriginal=/^data:image\//.test(record.sourceDataURL||''),brandLabel=PatternEngine.catalogs().find(c=>c.id===record.brand)?.label||'图像取色';
 return `<div class="pattern-reference-heading"><div><span>我的图纸 · 独立参考</span><strong title="${escapeHTML(record.name)}">${escapeHTML(record.name)}</strong><small>${record.width} × ${record.height} · ${escapeHTML(brandLabel)}</small></div>${phone?'':`<button data-action="ref-collapse" aria-label="折叠右侧参考框" title="折叠参考框">${icon('close')}</button>`}</div><div class="pattern-reference-tabs" role="group" aria-label="参考图显示方式">${[['original','原图'],['color','色块'],['codes','色号']].map(([value,label])=>`<button data-action="ref-mode" data-id="${value}" class="${mode===value?'active':''}" aria-pressed="${mode===value}" ${value==='original'&&!hasOriginal?'disabled title="这份图纸没有保存原图"':''}>${label}</button>`).join('')}</div><div class="pattern-reference-art"><canvas data-pattern-reference-canvas tabindex="0" role="application" aria-label="独立参考图。拖动平移，滚轮或双指缩放，点击色块选中真实品牌色号。"></canvas></div><div class="pattern-reference-tools"><button data-action="ref-zoom" data-id="out" aria-label="缩小参考图">${icon('minus')}</button><span data-reference-zoom>100%</span><button data-action="ref-zoom" data-id="in" aria-label="放大参考图">${icon('plus')}</button><button data-action="ref-fit" aria-label="查看完整参考图">${icon('expand')}</button><button data-action="ref-settings" aria-label="设置画板蓝图与参考图">${icon('more')}</button></div><p class="pattern-reference-tip" data-reference-color role="status">点击色块选豆 · 拖动查看细节</p>`;
}
function disposePatternReference(){
 patternReferenceDialogDispose?.();patternReferenceSettingsDispose?.();
 patternReferenceMountSignal?.abort();patternReferenceMountSignal=null;patternReferenceViewers.forEach(viewer=>viewer.dispose());patternReferenceViewers=[];
 document.querySelectorAll('[data-pattern-reference-controls]').forEach(node=>node.remove());
 if(patternReferenceShell){const workspace=patternReferenceShell.querySelector('.large-board-workspace');if(workspace)patternReferenceShell.replaceWith(workspace);else patternReferenceShell.remove();patternReferenceShell=null;}
}
function mountPatternReference(){
 disposePatternReference();const ref=attachedPatternReference(),workspace=document.querySelector('.fixed-editor .large-board-workspace');if(!ref||!workspace)return;
 const controller=new AbortController();patternReferenceMountSignal=controller;
 const controls=document.createElement('div');controls.className='pattern-reference-controls';controls.dataset.patternReferenceControls='';controls.innerHTML=`<button data-action="ref-panel" aria-label="${innerWidth<=760?'打开参考图':'展开右侧参考框'}">${icon('book')} 参考图</button><button data-action="ref-blueprint-toggle" class="${ref.blueprint?'active':''}" aria-pressed="${Boolean(ref.blueprint)}" ${referenceCanFit()?'':'disabled'} title="显示或隐藏画板蓝图">${icon('eye')} 蓝图${ref.blueprint?'开':'关'}</button><button data-action="ref-settings" aria-label="设置蓝图">${icon('more')}</button>`;workspace.querySelector('.board-area').append(controls);
 const panelVisible=patternReferenceInline()&&ref.reference!==false&&ref.expanded!==false;
 if(panelVisible){const shell=document.createElement('div');shell.className='pattern-reference-shell';shell.style.setProperty('--reference-width',Math.max(220,Math.min(420,Number(ref.widthPx)||280))+'px');workspace.before(shell);shell.append(workspace);patternReferenceShell=shell;
  const panel=document.createElement('aside');panel.className='pattern-reference-panel';panel.setAttribute('aria-label','拼豆图纸参考框');panel.innerHTML=patternReferenceMarkup(ref);shell.prepend(panel);
  const divider=document.createElement('div');divider.className='pattern-reference-divider';divider.tabIndex=0;divider.setAttribute('role','separator');divider.setAttribute('aria-label','调整参考框宽度');divider.setAttribute('aria-orientation','vertical');divider.setAttribute('aria-valuemin','220');divider.setAttribute('aria-valuemax','420');divider.setAttribute('aria-valuenow',String(Math.max(220,Math.min(420,Number(ref.widthPx)||280))));panel.after(divider);
  const widthLimit=()=>Math.min(420,Math.max(220,shell.getBoundingClientRect().width*.43));const resize=value=>{ref.widthPx=Math.max(220,Math.min(widthLimit(),value));shell.style.setProperty('--reference-width',ref.widthPx+'px');divider.setAttribute('aria-valuenow',String(Math.round(ref.widthPx)));};let dragging=false,startX=0,startWidth=0;
  divider.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();dragging=true;startX=event.clientX;startWidth=panel.getBoundingClientRect().width;divider.setPointerCapture(event.pointerId);},{signal:controller.signal});divider.addEventListener('pointermove',event=>{if(!dragging)return;event.preventDefault();resize(startWidth-event.clientX+startX);},{signal:controller.signal});const finish=()=>{if(dragging){dragging=false;save();}};divider.addEventListener('pointerup',finish,{signal:controller.signal});divider.addEventListener('pointercancel',finish,{signal:controller.signal});divider.addEventListener('lostpointercapture',finish,{signal:controller.signal});divider.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;event.preventDefault();resize(event.key==='Home'?280:(Number(ref.widthPx)||280)+(event.key==='ArrowLeft'?-16:16));save();},{signal:controller.signal});
  patternReferenceViewers.push(createPatternReferenceViewport(panel.querySelector('canvas'),ref));
 }
 let priorInline=patternReferenceInline();window.addEventListener('resize',()=>{const inline=patternReferenceInline();if(inline!==priorInline){priorInline=inline;mountPatternReference();fitFixedScene();}},{signal:controller.signal});
 fitFixedScene();
}
function createPatternReferenceViewport(canvas,ref){
 const ctx=canvas.getContext('2d'),controller=new AbortController(),points=new Map(),grid=referenceGrid(),record=ref.record;let alive=true,width=1,height=1,raf=0,start=null,moved=false,pinch=null,hover=null;
 if(!ref.view||typeof ref.view!=='object')ref.view={zoom:1,panX:0,panY:0};const stored=ref.view;stored.zoom=Math.max(.5,Math.min(32,Number(stored.zoom)||1));stored.panX=Number(stored.panX)||0;stored.panY=Number(stored.panY)||0;
 const image=new Image();image.onload=()=>schedule();if(/^data:image\//.test(record.sourceDataURL||''))image.src=record.sourceDataURL;
 const raster=document.createElement('canvas');raster.width=record.width;raster.height=record.height;const rasterContext=raster.getContext('2d');
 if(grid){const pixels=rasterContext.createImageData(record.width,record.height),colors=new Map();for(let y=0;y<record.height;y++)for(let x=0;x<record.width;x++){const entry=palette[grid[y]?.[x]];if(!entry)continue;let rgba=colors.get(entry.hex);if(!rgba){const n=parseInt(entry.hex.slice(1),16);rgba=[n>>16,(n>>8)&255,n&255,255];colors.set(entry.hex,rgba);}pixels.data.set(rgba,(y*record.width+x)*4);}rasterContext.putImageData(pixels,0,0);}
 const layout=()=>{const step=Math.max(.01,Math.min((width-24)/record.width,(height-24)/record.height))*stored.zoom;return{step,left:width/2-record.width*step/2+stored.panX,top:height/2-record.height*step/2+stored.panY};};
 const point=event=>{const rect=canvas.getBoundingClientRect();return{x:(event.clientX-rect.left)*width/(rect.width||width),y:(event.clientY-rect.top)*height/(rect.height||height)};};
 const cell=p=>{const v=layout();return{x:Math.floor((p.x-v.left)/v.step),y:Math.floor((p.y-v.top)/v.step)};};
 const selected=p=>{const c=cell(p),key=grid?.[c.y]?.[c.x];if(!key||key==='.'||!palette[key])return;const catalogId='pattern-'+record.brand;if(paletteCatalogs()[catalogId])handlePaletteCatalog(catalogId);handlePaletteAction({dataset:{id:key}},'color');canvas.closest('.pattern-reference-panel,.pattern-reference-dialog-body')?.querySelector('[data-reference-color]')?.replaceChildren(document.createTextNode('已选 '+paletteColorLabel(key)));canvas.dataset.selectedColor=key;hover=c;schedule();};
 function draw(){if(!alive)return;const v=layout(),mode=ref.displayMode||'color';ctx.clearRect(0,0,width,height);ctx.fillStyle='#eeefe7';ctx.fillRect(0,0,width,height);ctx.save();ctx.fillStyle='#fafaf4';ctx.shadowColor='#56604714';ctx.shadowBlur=12;ctx.shadowOffsetY=3;ctx.fillRect(v.left,v.top,record.width*v.step,record.height*v.step);ctx.restore();
  if(mode==='original'&&image.complete&&image.naturalWidth){const ratio=Math.min(record.width*v.step/image.naturalWidth,record.height*v.step/image.naturalHeight),w=image.naturalWidth*ratio,h=image.naturalHeight*ratio;ctx.drawImage(image,v.left+(record.width*v.step-w)/2,v.top+(record.height*v.step-h)/2,w,h);}else if(grid){
   const minX=Math.max(0,Math.floor(-v.left/v.step)),maxX=Math.min(record.width-1,Math.ceil((width-v.left)/v.step)),minY=Math.max(0,Math.floor(-v.top/v.step)),maxY=Math.min(record.height-1,Math.ceil((height-v.top)/v.step));
   ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(raster,v.left,v.top,record.width*v.step,record.height*v.step);ctx.restore();
   if(v.step>=8){ctx.strokeStyle='#65705735';ctx.lineWidth=.5;ctx.beginPath();for(let x=minX;x<=maxX+1;x++){ctx.moveTo(v.left+x*v.step,Math.max(0,v.top));ctx.lineTo(v.left+x*v.step,Math.min(height,v.top+record.height*v.step));}for(let y=minY;y<=maxY+1;y++){ctx.moveTo(Math.max(0,v.left),v.top+y*v.step);ctx.lineTo(Math.min(width,v.left+record.width*v.step),v.top+y*v.step);}ctx.stroke();}
   if(mode==='codes'&&v.step>=15){ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`500 ${Math.min(12,v.step*.28)}px sans-serif`;for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const entry=palette[grid[y]?.[x]];if(!entry)continue;const code=entry.code||entry.name||'';if(ctx.measureText(code).width>v.step*.9)continue;const rgb=parseInt(entry.hex.slice(1),16),light=((rgb>>16)*.2126+((rgb>>8)&255)*.7152+(rgb&255)*.0722)>128;ctx.fillStyle=light?'#333b2f':'#fffef8';ctx.fillText(code,v.left+(x+.5)*v.step,v.top+(y+.5)*v.step,v.step*.9);}}
  }
  if(hover&&mode!=='original'&&grid?.[hover.y]?.[hover.x]&&grid[hover.y][hover.x]!=='.'){ctx.strokeStyle='#fffdf7';ctx.lineWidth=2;ctx.strokeRect(v.left+hover.x*v.step+1,v.top+hover.y*v.step+1,v.step-2,v.step-2);ctx.strokeStyle='#61724d';ctx.lineWidth=.75;ctx.strokeRect(v.left+hover.x*v.step,v.top+hover.y*v.step,v.step,v.step);}
  canvas.closest('.pattern-reference-panel,.pattern-reference-dialog-body')?.querySelector('[data-reference-zoom]')?.replaceChildren(document.createTextNode(Math.round(stored.zoom*100)+'%'));canvas.dataset.zoom=stored.zoom.toFixed(2);canvas.dataset.patternId=record.id||ref.patternId||'';canvas.dataset.mode=mode;
 }
 function schedule(){if(!raf&&alive)raf=requestAnimationFrame(()=>{raf=0;draw();});}
 function zoomBy(factor,p={x:width/2,y:height/2}){const next=Math.max(.5,Math.min(32,stored.zoom*factor)),ratio=next/stored.zoom;stored.panX=(p.x-width/2)-(p.x-width/2-stored.panX)*ratio;stored.panY=(p.y-height/2)-(p.y-height/2-stored.panY)*ratio;stored.zoom=next;schedule();}
 const listen=(name,handler,options={})=>canvas.addEventListener(name,handler,{...options,signal:controller.signal});
 listen('pointerdown',event=>{if(event.pointerType==='mouse'&&event.button!==0)return;event.preventDefault();event.stopPropagation();canvas.setPointerCapture(event.pointerId);const p=point(event);points.set(event.pointerId,p);if(points.size===1){start=p;moved=false;canvas.classList.add('is-dragging');}else{moved=true;const ps=[...points.values()];pinch={distance:Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y),center:{x:(ps[0].x+ps[1].x)/2,y:(ps[0].y+ps[1].y)/2}};}});
 listen('pointermove',event=>{const p=point(event),old=points.get(event.pointerId);hover=cell(p);if(!old){schedule();return;}event.preventDefault();event.stopPropagation();points.set(event.pointerId,p);if(points.size>1){const ps=[...points.values()],distance=Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y),center={x:(ps[0].x+ps[1].x)/2,y:(ps[0].y+ps[1].y)/2};if(pinch?.distance){zoomBy(distance/pinch.distance,center);stored.panX+=center.x-pinch.center.x;stored.panY+=center.y-pinch.center.y;}pinch={distance,center};moved=true;}else{if(start&&Math.hypot(p.x-start.x,p.y-start.y)>5)moved=true;if(moved){stored.panX+=p.x-old.x;stored.panY+=p.y-old.y;}}schedule();});
 const release=(event,cancel=false)=>{if(!points.has(event.pointerId))return;event.preventDefault();event.stopPropagation();const p=point(event);if(!cancel&&!moved&&points.size===1&&(ref.displayMode||'color')!=='original')selected(p);points.delete(event.pointerId);pinch=null;if(!points.size){start=null;canvas.classList.remove('is-dragging');saveSoon();}else moved=true;schedule();};
 listen('pointerup',event=>release(event));listen('pointercancel',event=>release(event,true));listen('lostpointercapture',event=>release(event,true));listen('pointerleave',()=>{if(!points.size)hover=null;schedule();});
 listen('wheel',event=>{event.preventDefault();event.stopPropagation();zoomBy(Math.exp(-event.deltaY*.0014),point(event));saveSoon();},{passive:false});
 listen('keydown',event=>{const map={ArrowLeft:[24,0],ArrowRight:[-24,0],ArrowUp:[0,24],ArrowDown:[0,-24]};if(map[event.key]){event.preventDefault();event.stopPropagation();stored.panX+=map[event.key][0];stored.panY+=map[event.key][1];schedule();saveSoon();}else if(['+','=','-','Home'].includes(event.key)){event.preventDefault();event.stopPropagation();if(event.key==='Home'){stored.zoom=1;stored.panX=stored.panY=0;schedule();}else zoomBy(event.key==='-'?1/1.25:1.25);saveSoon();}});
 const observer=new ResizeObserver(()=>{if(!alive)return;const rect=canvas.parentElement.getBoundingClientRect();if(rect.width<=0||rect.height<=0)return;const nextWidth=Math.max(1,Math.round(rect.width)),nextHeight=Math.max(1,Math.round(rect.height));if(width===nextWidth&&height===nextHeight)return;width=nextWidth;height=nextHeight;canvas.width=width;canvas.height=height;schedule();});observer.observe(canvas.parentElement);
 schedule();return{canvas,draw:schedule,zoomBy,fit(){stored.zoom=1;stored.panX=stored.panY=0;schedule();},dispose(){alive=false;cancelAnimationFrame(raf);controller.abort();observer.disconnect();image.onload=null;points.clear();raster.width=raster.height=1;}};
}
function openPatternReferencePanel(){
 const ref=attachedPatternReference();if(!ref)return;ref.reference=true;ref.expanded=true;save();if(patternReferenceInline()){mountPatternReference();return;}
 patternReferenceSettingsDispose?.();patternReferenceDialogDispose?.();openFixedPanel('pattern-reference','我的参考图',`<div class="fixed-panel-body pattern-reference-dialog-body">${patternReferenceMarkup(ref,true)}</div>`,`<button class="button" data-action="close">回到拼豆板</button>`);dialog.classList.add('pattern-reference-dialog');const viewer=createPatternReferenceViewport(dialog.querySelector('[data-pattern-reference-canvas]'),ref);patternReferenceViewers.push(viewer);
 const close=()=>{viewer.dispose();patternReferenceViewers=patternReferenceViewers.filter(item=>item!==viewer);dialog.classList.remove('pattern-reference-dialog');dialog.removeEventListener('close',close);patternReferenceDialogDispose=null;save();};patternReferenceDialogDispose=close;dialog.addEventListener('close',close,{once:true});
}
function openPatternReferenceSettings(){
 const ref=attachedPatternReference();if(!ref)return;const size=draftDimensions(),record=ref.record,maxX=Math.max(0,size.cols-record.width),maxY=Math.max(0,size.rows-record.height),fits=referenceCanFit();
 patternReferenceDialogDispose?.();patternReferenceSettingsDispose?.();
 openFixedPanel('pattern-reference-settings','图纸参考设置',`<p class="fixed-panel-intro">${escapeHTML(record.name)} · ${record.width} × ${record.height} · 参考层不计入实际拼豆。</p><div class="fixed-panel-body pattern-reference-settings-body"><label class="reference-setting-row"><span>在拼豆板下方显示蓝图${fits?'':' · 当前板子放不下'}</span><input data-ref-setting="blueprint" type="checkbox" ${ref.blueprint&&fits?'checked':''} ${fits?'':'disabled'}></label><label class="reference-setting-row"><span>显示右侧参考框</span><input data-ref-setting="reference" type="checkbox" ${ref.reference!==false?'checked':''}></label><label class="reference-setting-row"><span>显示蓝图色号</span><input data-ref-setting="showCodes" type="checkbox" ${ref.showCodes?'checked':''}></label><label class="reference-opacity"><span>蓝图透明度 <strong data-ref-opacity-value>${Math.round((ref.opacity??.30)*100)}%</strong></span><input data-ref-setting="opacity" aria-label="蓝图透明度" type="range" min="5" max="75" value="${Math.round((ref.opacity??.30)*100)}"></label><div class="reference-offsets"><label>起始列<input data-ref-setting="offsetX" aria-label="蓝图起始列" type="number" min="1" max="${maxX+1}" value="${(ref.offsetX||0)+1}" ${fits?'':'disabled'}></label><label>起始行<input data-ref-setting="offsetY" aria-label="蓝图起始行" type="number" min="1" max="${maxY+1}" value="${(ref.offsetY||0)+1}" ${fits?'':'disabled'}></label><button data-action="ref-center" ${fits?'':'disabled'}>居中</button></div><p class="reference-setting-note">色号在放大后显示；摆好的豆子始终盖在蓝图上方。</p></div>`,`<div class="reference-settings-footer"><button class="button outline" data-action="ref-clear">移除这份参考</button><button class="button" data-action="ref-settings-done">回到创作</button></div>`);
 const controller=new AbortController(),body=dialog.querySelector('.pattern-reference-settings-body');const input=event=>{const key=event.target.dataset.refSetting;if(!key)return;if(['blueprint','reference','showCodes'].includes(key)){ref[key]=event.target.checked;if(key==='reference')ref.expanded=event.target.checked;}else if(key==='opacity'){ref.opacity=Math.max(.05,Math.min(.75,Number(event.target.value)/100));body.querySelector('[data-ref-opacity-value]').textContent=Math.round(ref.opacity*100)+'%';}else{const maximum=key==='offsetX'?maxX:maxY;ref[key]=Math.max(0,Math.min(maximum,Math.round(Number(event.target.value)||1)-1));if(event.type==='change')event.target.value=ref[key]+1;}patternReferenceSave();};body.addEventListener('input',input,{signal:controller.signal});body.addEventListener('change',input,{signal:controller.signal});const cleanup=()=>{controller.abort();dialog.removeEventListener('close',close);patternReferenceSettingsDispose=null;};const close=()=>{cleanup();if(typeof route==='undefined'||route==='editor')mountPatternReference();};patternReferenceSettingsDispose=cleanup;dialog.addEventListener('close',close,{once:true});
}
function handlePatternReferenceAction(action,id,button){
 if(!action.startsWith('ref-'))return false;const ref=attachedPatternReference();if(!ref)return true;
 if(action==='ref-panel')openPatternReferencePanel();
 else if(action==='ref-collapse'){ref.expanded=false;ref.reference=false;save();mountPatternReference();}
 else if(action==='ref-blueprint-toggle'){if(referenceCanFit()){ref.blueprint=!ref.blueprint;save();drawBoard();mountPatternReference();}}
 else if(action==='ref-settings')openPatternReferenceSettings();
 else if(action==='ref-settings-done')dialog.close();
 else if(action==='ref-mode'&&['original','color','codes'].includes(id)){ref.displayMode=id;save();document.querySelectorAll('[data-action="ref-mode"]').forEach(node=>{const active=node.dataset.id===id;node.classList.toggle('active',active);node.setAttribute('aria-pressed',String(active));});patternReferenceViewers.forEach(viewer=>viewer.draw());}
 else if(action==='ref-zoom'||action==='ref-fit'){const panel=button?.closest('.pattern-reference-panel,.pattern-reference-dialog-body'),viewer=patternReferenceViewers.find(item=>panel?.contains(item.canvas));if(viewer){action==='ref-fit'?viewer.fit():viewer.zoomBy(id==='out'?1/1.25:1.25);save();}}
 else if(action==='ref-center'){const size=draftDimensions();ref.offsetX=Math.max(0,Math.floor((size.cols-ref.record.width)/2));ref.offsetY=Math.max(0,Math.floor((size.rows-ref.record.height)/2));dialog.querySelector('[data-ref-setting="offsetX"]').value=ref.offsetX+1;dialog.querySelector('[data-ref-setting="offsetY"]').value=ref.offsetY+1;patternReferenceSave();}
 else if(action==='ref-clear'){delete state.draft.patternReference;patternReferenceCache=null;save();drawBoard();dialog.close();mountPatternReference();toast('参考图已移除，摆好的拼豆会保留。');}
 return true;
}
